//! Gold: `page_index` is 1:1 with the live `harness/electronics/page_index.py`.
//!
//! `tests/fixtures/gold/page_index_v1.json` was generated by
//! `scripts/gold_page_index.py` — document cases feed a mock document (TOC +
//! page texts) through `index_document`, kernel cases call the pure readers.
//! `locator.locate_pin_definition_pages` is a PDF-layer reader (§5.5, not yet
//! ported), so its outputs travel as `pin_results` and the gold test's
//! `locate` callback replays them — while asserting the port recomputes the
//! SAME `single_package` decision the reference passed (captured in
//! `pin_calls`).
//!
//! The cases pin the traps the reader exists for: TOC lanes first, page-text
//! fallback only for lanes the TOC missed, the 3..=180 heading window,
//! `classify_section` reporting lanes in `LANE_PATTERNS` order (both
//! `pin_or_ball` and `pin_semantics` fire on "Pin and ball descriptions"),
//! the single-package relaxation gated on BOTH one request and front matter
//! naming at most that family, `package_requests_from_ground_truth` taking
//! the printed count per package string, and the 64-hex document digest
//! guard.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::cast_possible_truncation,
    clippy::doc_markdown,
    clippy::panic,
    reason = "gold tests assert on their own fixtures"
)]

use std::path::PathBuf;

use serde_json::Value;

use dw_recon::page_index::{
    classify_section, index_document, package_requests_from_ground_truth, printed_package_families,
};

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/page_index_v1.json")
}

fn gold() -> Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

#[test]
fn every_case_matches_the_live_reference() {
    let g = gold();
    let mut checked = 0;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        match case["kind"].as_str().unwrap() {
            "document" => {
                let input = &case["input"];
                let pages: Vec<String> = input["pages"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|p| p.as_str().unwrap().to_string())
                    .collect();
                let toc: Vec<Value> = input["toc"].as_array().unwrap().clone();
                let requests: Vec<(String, i64)> = input["package_requests"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|r| (r[0].as_str().unwrap().to_string(), r[1].as_i64().unwrap()))
                    .collect();
                let fallback_max = input["fallback_maximum_pages"].as_u64().map(|n| n as usize);
                let pin_results = &input["pin_results"];
                let pin_calls = input["pin_calls"].as_array().unwrap();
                let mut call_index = 0usize;
                let outcome = index_document(
                    &pages,
                    &toc,
                    input["document_sha256"].as_str().unwrap(),
                    input["source_path"].as_str().unwrap(),
                    &requests,
                    fallback_max,
                    |package, pins, single_package| {
                        let call = &pin_calls[call_index];
                        assert_eq!(
                            call["package"].as_str().unwrap(),
                            package,
                            "case {name}: locate call {} package",
                            call_index + 1
                        );
                        assert_eq!(
                            call["pins"].as_i64().unwrap(),
                            pins,
                            "case {name}: locate call {} pins",
                            call_index + 1
                        );
                        assert_eq!(
                            call["single_package"].as_bool().unwrap(),
                            single_package,
                            "case {name}: locate call {} single_package",
                            call_index + 1
                        );
                        call_index += 1;
                        pin_results[format!("{package}|{pins}")].clone()
                    },
                );
                assert_eq!(
                    call_index,
                    pin_calls.len(),
                    "case {name}: locator call count"
                );
                match outcome {
                    Ok(got) => {
                        assert!(
                            case["error"].is_null(),
                            "case {name}: expected error {}",
                            case["error"]
                        );
                        assert_eq!(got, case["expected"], "case {name}");
                    }
                    Err(error) => {
                        assert_eq!(error, case["error"].as_str().unwrap(), "case {name}");
                    }
                }
            }
            "classify_section" => {
                let got = classify_section(case["input"]["title"].as_str().unwrap());
                assert_eq!(
                    serde_json::to_value(got).unwrap(),
                    case["expected"],
                    "case {name}"
                );
            }
            "package_requests" => {
                let records: Vec<Value> = case["input"]["records"].as_array().unwrap().clone();
                let got = package_requests_from_ground_truth(&records);
                let expected: Vec<(String, i64)> =
                    serde_json::from_value(case["expected"].clone()).unwrap();
                assert_eq!(got, expected, "case {name}");
            }
            "printed_package_families" => {
                let pages: Vec<String> = case["input"]["pages"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|p| p.as_str().unwrap().to_string())
                    .collect();
                let got: Vec<String> = printed_package_families(&pages).into_iter().collect();
                assert_eq!(
                    serde_json::to_value(got).unwrap(),
                    case["expected"],
                    "case {name}"
                );
            }
            other => panic!("unknown gold case kind {other}"),
        }
        checked += 1;
    }
    assert_eq!(checked, g["cases"].as_array().unwrap().len());
}
